#!/usr/bin/env bash
# Contratos de distribución: identidad, assets y superficie de integración.

set -Eeuo pipefail

ROOT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)"
failures=0
fail() { printf 'CONTRACT ERROR: %s\n' "$1" >&2; failures=$((failures + 1)); }
ok() { printf '  OK    %s\n' "$1"; }

[[ -f "$ROOT_DIR/ltools.sh" ]] || fail 'falta ltools.sh'
[[ -f "$ROOT_DIR/ltools-cli.sh" ]] || fail 'falta el lanzador CLI Linux'
if [[ ! -x "$ROOT_DIR/ltools" && ! -x "$ROOT_DIR/ltools.sh" ]]; then
    fail 'falta el entrypoint portable ltools o su lanzador Linux'
fi
if [[ ! -x "$ROOT_DIR/ltools-cli" && ! -x "$ROOT_DIR/ltools-cli.sh" ]]; then
    fail 'falta el entrypoint portable ltools-cli o su lanzador Linux'
fi
[[ -x "$ROOT_DIR/scripts/build.sh" ]] || fail 'falta el menú unificado Linux en scripts/build.sh'
[[ -f "$ROOT_DIR/scripts/build.ps1" ]] || fail 'falta el builder/menú unificado Windows en scripts/build.ps1'
grep -Fq 'Preview y ejecutar' "$ROOT_DIR/scripts/build.sh" || fail 'menú Linux sin sección de preview'
grep -Fq 'Probar lo ya compilado' "$ROOT_DIR/scripts/build.sh" || fail 'menú Linux sin sección de pruebas sin recompilar'
grep -Fq 'E2E de menús GUI y flujos funcionales' "$ROOT_DIR/scripts/build.sh" || fail 'menú de pruebas Linux no distingue la auditoría nativa independiente'
grep -Fq -- '--require-gui --binary "$RELEASE_BIN"' "$ROOT_DIR/scripts/build.sh" || fail 'pruebas manuales Linux permiten omitir la GUI'
grep -Fq -- '--require-dependencies --binary "$RELEASE_BIN"' "$ROOT_DIR/scripts/build.sh" || fail 'pruebas manuales Linux permiten omitir dependencias'
grep -Fq 'tests/scripts-syntax.sh' "$ROOT_DIR/scripts/build.sh" || fail 'builder/menú Linux no ofrece parseo de scripts sin compilar'
grep -Fq 'third-party-licenses.sh' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no integra el paquete de licencias de dependencias'
grep -Fq 'ssh-signing.sh' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no integra firmas SSH de release'
[[ -f "$ROOT_DIR/LICENSE" ]] || fail 'falta la licencia MIT del proyecto'
grep -Fq 'https://github.com/Darkeiser003' "$ROOT_DIR/LICENSE" || fail 'la licencia del proyecto no enlaza al perfil de GitHub del titular'
grep -Fq 'SHA256SUMS.txt.sshsig' "$ROOT_DIR/tests/release-e2e.sh" || fail 'E2E de release no verifica la firma SSH'
[[ -f "$ROOT_DIR/tests/ssh-signing.sh" ]] || fail 'falta la prueba funcional de firma SSH de release'
[[ -f "$ROOT_DIR/tests/third-party-licenses.sh" ]] || fail 'falta la prueba funcional del paquete de licencias'
grep -Fq 'THIRD-PARTY-LICENSES/INDEX.txt' "$ROOT_DIR/tests/linux/tarball-e2e.sh" || fail 'E2E del tarball no valida los avisos de licencias incluidos'
grep -Fq 'LICENSE' "$ROOT_DIR/tests/linux/tarball-e2e.sh" || fail 'E2E del tarball no valida la licencia del proyecto'
grep -Fq 'New-LToolsThirdPartyLicenseBundle' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no genera los avisos de dependencias'
grep -Fq 'THIRD-PARTY-LICENSES-windows.zip' "$ROOT_DIR/scripts/lib/build-state.ps1" || fail 'estado incremental Windows no vigila el archivo de licencias'
grep -Fq 'crate = "webpki-roots", allow = ["CDLA-Permissive-2.0"]' "$ROOT_DIR/deny.toml" || fail 'cargo-deny no limita CDLA a los datos de raíces TLS'
grep -Fxq '    "ISC",' "$ROOT_DIR/deny.toml" || fail 'cargo-deny no contempla ISC requerido por rustls-webpki/ring'
grep -Fq 'cargo deny --config "$ROOT_DIR/deny.toml" check' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no fija la política cargo-deny versionada'
[[ -f "$ROOT_DIR/tests/scripts-syntax.sh" ]] || fail 'falta el comprobador de sintaxis de scripts'
[[ -f "$ROOT_DIR/tests/static-security.sh" ]] || fail 'falta la revisión estática local de scripts/workflows'
grep -Fq 'tests/static-security.sh' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no ejecuta la revisión estática'
grep -Fq -- '--security-review' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no ofrece revisión estática obligatoria'
grep -Fq 'Invoke-StaticSecurityReview' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no revisa scripts/workflows cuando puede'
grep -Fq "Get-Command 'zizmor'" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows omite zizmor local cuando está disponible'
grep -Fq "Invoke-NativeCommand 'zizmor' @('--offline', \$zizmorInput)" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no ofrece revisión local offline de zizmor'
grep -Fq 'no se verifican referencias remotas' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no declara que zizmor offline omite referencias remotas'
grep -Fq 'zizmor .github' "$ROOT_DIR/tests/static-security.sh" || fail 'revisión local Linux no ejecuta zizmor online cuando hay token'
grep -Fq 'no se verifican referencias remotas de acciones' "$ROOT_DIR/tests/static-security.sh" || fail 'revisión Linux no declara el alcance limitado de zizmor offline'
grep -Fq '[switch]$SecurityReview' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no permite exigir la revisión estática'
grep -Fq 'actionlint@v1.7.12' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no instala actionlint para la revisión estricta'
grep -Fq 'Compilar solo el backend GUI' "$ROOT_DIR/scripts/build.sh" || fail 'menú Linux sin build de backend aislada'
grep -Fq 'Build rápida de desarrollo: sin paquetes, tests, smoke, E2E ni Wine' "$ROOT_DIR/scripts/build.sh" || fail 'menú Linux no advierte que la build rápida omite las pruebas'
grep -Fq -- '--fast --no-tests --no-package' "$ROOT_DIR/scripts/build.sh" || fail 'perfil rápido del menú no desactiva explícitamente cargo test'
grep -Fq 'Limpiar artefactos Windows' "$ROOT_DIR/scripts/build.ps1" || fail 'menú Windows sin limpieza de artefactos'
grep -Fq 'perfil rápido, conserva las pruebas' "$ROOT_DIR/scripts/build.ps1" || fail 'menú Windows confunde perfil rápido con omitir pruebas'
grep -Fq 'El smoke también necesita ltools-cli.exe' "$ROOT_DIR/scripts/build.ps1" || fail 'menú Windows no verifica el perfil CLI previo al smoke'
grep -Fxq '/dist/' "$ROOT_DIR/.gitignore" || fail 'Git no excluye la carpeta de salida predeterminada dist'
grep -Fxq '/rust/dist/' "$ROOT_DIR/.gitignore" || fail 'Git no excluye residuos antiguos de salida bajo rust/dist'
grep -Fq 'all) generated=(dist rust/dist' "$ROOT_DIR/scripts/build.sh" || fail 'limpiador completo no incluye rust/dist'
grep -Fq 'dist) generated=(dist rust/dist)' "$ROOT_DIR/scripts/build.sh" || fail 'limpiador de dist no incluye rust/dist'
grep -Fq 'fuzz/target fuzz/artifacts reports' "$ROOT_DIR/scripts/build.sh" || fail 'limpiador completo omite salidas de fuzzing e informes'
grep -Fq 'targets) generated=(rust/target fuzz/target' "$ROOT_DIR/scripts/build.sh" || fail 'limpiador de targets omite fuzz/target'
grep -Fq 'fuzz/target' "$ROOT_DIR/README.md" && grep -Fq -- '--keep-release --yes' "$ROOT_DIR/README.md" || fail 'README no documenta la limpieza completa conservando release'
grep -Fxq '/release/' "$ROOT_DIR/.gitignore" || fail 'Git no excluye la carpeta de releases locales predeterminada'
grep -Fq 'fn cli_all_index()' "$ROOT_DIR/rust/src/guides.rs" || fail 'guide cli all no agrega las guías detalladas de sus familias'
grep -Fq 'ÍNDICE DETALLADO DE FAMILIAS CLI' "$ROOT_DIR/tests/linux/menu-e2e.sh" || fail 'E2E no valida el índice CLI detallado'
for github_workflow in ci.yml workflow-security.yml dependency-review.yml scorecard.yml codeql.yml osv-scanner.yml; do
    [[ -f "$ROOT_DIR/.github/workflows/$github_workflow" ]] ||
        fail "falta el workflow GitHub Actions $github_workflow"
done
while IFS= read -r action_ref; do
    action_ref="${action_ref#*@}"
    if [[ ! "$action_ref" =~ ^[0-9a-f]{40}$ ]]; then
        fail "acción GitHub sin SHA completo e inmutable: $action_ref"
    fi
done < <(rg --no-filename '^[[:space:]]*uses:[[:space:]]+' "$ROOT_DIR/.github/workflows" -g '*.yml' -g '*.yaml' | sed -E 's/^[[:space:]]*uses:[[:space:]]+([^[:space:]]+).*/\1/')
# Dependabot actualiza los SHA de estas acciones; validar el destino aquí y
# el formato inmutable arriba evita bloquear sus PR por una versión antigua.
grep -Fq 'branches: [main]' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no se ejecuta en main'
grep -Fq '  pull_request:' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no revalida las dependencias en cada actualización de pull request'
grep -Fq '  pull_request:' "$ROOT_DIR/.github/workflows/dependency-review.yml" || fail 'Dependency Review no analiza pull requests automáticamente'
grep -Fq -- '--windows-wine --no-appimage --allow-unsigned' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI Linux no ejecuta build completa con Wine'
grep -Fq -- '-Force -AllowUnsigned -NonInteractive' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI Windows no fuerza build y pruebas nativas completas'
grep -Fq -- '--strict-security' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'la build Linux de CI no exige ambas auditorías Rust'
grep -Fq 'ripgrep' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no instala ripgrep, requerido por los contratos y scripts de prueba'
grep -Fq 'taiki-e/install-action@' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'la build estricta de CI no instala las herramientas Cargo verificadas'
grep -Fq 'tool: cargo-audit,cargo-deny' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'la build estricta no prepara cargo-audit y cargo-deny'
grep -Fq 'rust/crates/native-argv/**' "$ROOT_DIR/.github/workflows/fuzz.yml" || fail 'ClusterFuzzLite no se activa al cambiar el parser nativo'
! grep -Fq 'security-events: write' "$ROOT_DIR/.github/workflows/fuzz.yml" || fail 'el workflow de fuzzing pide permiso de publicación de hallazgos que no necesita'
grep -Fq 'cargo fuzz build --fuzz-dir fuzz -O native-argv' "$ROOT_DIR/.clusterfuzzlite/build.sh" || fail 'ClusterFuzzLite no compila el target de parser'
grep -Fq 'max_total_time' "$ROOT_DIR/README.md" || fail 'README no documenta cómo ejecutar fuzzing local acotado'
grep -Fq '"ltools-argv"' "$ROOT_DIR/rust/Cargo.lock" || fail 'Cargo.lock principal no registra el parser separado'
grep -Fq 'name = "ltools-fuzz"' "$ROOT_DIR/fuzz/Cargo.lock" || fail 'fuzz no tiene lockfile reproducible'
grep -Fq 'directory: /fuzz' "$ROOT_DIR/.github/dependabot.yml" || fail 'Dependabot no mantiene las dependencias del fuzzer'
grep -Fq 'libfuzzer-sys = "0.4"' "$ROOT_DIR/fuzz/Cargo.toml" || fail 'el fuzzer no fija libfuzzer-sys en su manifiesto aislado'
grep -Fq 'crate = "libfuzzer-sys", allow = ["NCSA"]' "$ROOT_DIR/fuzz/deny.toml" || fail 'cargo-deny no limita NCSA al crate de fuzzing'
! grep -Fq 'crate = "libfuzzer-sys"' "$ROOT_DIR/deny.toml" || fail 'la política principal no debe contener excepciones del fuzzer'
grep -Fq "LTOOLS_REQUIRE_LOOPBACK_TESTS: '1'" "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI permite omitir la integración HTTP local del actualizador'
grep -Fq 'production_http_transport_fetches_metadata_and_streams_artifacts' "$ROOT_DIR/rust/src/updater.rs" || fail 'el cliente HTTP de producción no tiene una E2E de transporte'
grep -Fq 'let account_label_width = (content_width * 48 / 100).clamp(120, 300);' "$ROOT_DIR/rust/src/gui.rs" || fail 'las etiquetas del formulario de cuentas Windows no se adaptan al ancho disponible'
grep -Fq 'gui_account_text("field_details")' "$ROOT_DIR/rust/src/gui.rs" || fail 'el formulario Windows no localiza los argumentos de cuenta'
grep -Fq 'options.write(true).create_new(true)' "$ROOT_DIR/rust/src/gui.rs" || fail 'el archivo temporal de contraseña no se crea de forma exclusiva'
grep -Fq 'options.mode(0o600)' "$ROOT_DIR/rust/src/gui.rs" || fail 'el archivo temporal de contraseña no nace con permisos privados en Unix'
grep -Fq 'TemporaryFileCleanup' "$ROOT_DIR/rust/src/gui.rs" || fail 'las GUI no limpian el archivo de contraseña al finalizar o fallar'
grep -Fq 'account_gui_labels_exist_in_every_terminal_language' "$ROOT_DIR/rust/src/i18n.rs" || fail 'faltan pruebas de localización de cuentas para los 15 idiomas'
grep -Fq 'let action_columns = if page == ACCOUNT_PAGE && content_width >= 840 {' "$ROOT_DIR/rust/src/gui.rs" || fail 'las acciones de cuentas Windows no se reorganizan para evitar solapar el botón Volver'
grep -Fq 'action_height, row_gap' "$ROOT_DIR/rust/src/gui.rs" || fail 'el menú de cuentas Windows no compacta sus filas en ventanas estrechas'
grep -Fq -- '--strict-security' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no ofrece auditoría de dependencias estricta'
grep -Fq -- '--security-review' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no exige escaneo estático dentro de la build Linux'
grep -Fq 'shellcheck' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no instala ShellCheck para la revisión estricta'
grep -Fq 'actionlint@v1.7.12' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'CI no instala actionlint para la revisión estricta'
grep -Fq 'ossf/scorecard-action@' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'falta la acción Scorecard'
grep -Fq 'github/codeql-action/upload-sarif@' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'Scorecard no publica SARIF en GitHub Code Scanning'
grep -Fq 'security-events: write' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'Scorecard no tiene permiso acotado para cargar hallazgos SARIF'
grep -Fq 'id-token: write' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'Scorecard no tiene permiso OIDC requerido para publicar resultados'
grep -Fq 'actions: read' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'Scorecard no tiene permiso mínimo para inspeccionar las automatizaciones del repositorio'
grep -Fq 'permissions: {}' "$ROOT_DIR/.github/workflows/scorecard.yml" || fail 'Scorecard no deniega permisos globales por defecto'
if grep -Fq 'pull_request:' "$ROOT_DIR/.github/workflows/scorecard.yml"; then
    fail 'Scorecard publica resultados con tokens de pull requests no confiables'
fi
grep -Fq 'zizmorcore/zizmor-action@' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'falta el análisis zizmor de workflows'
grep -Fq 'inputs: ./.github/' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'zizmor no examina todos los workflows y automatizaciones de .github'
grep -Fq 'version: 1.28.0' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'la versión del analizador zizmor no es reproducible'
grep -Fq 'github/codeql-action/init@' "$ROOT_DIR/.github/workflows/codeql.yml" || fail 'falta la acción de inicialización CodeQL'
grep -Fq 'language: [rust, actions]' "$ROOT_DIR/.github/workflows/codeql.yml" || fail 'CodeQL no cubre Rust y GitHub Actions como la terminal'
grep -Fq 'build-mode: none' "$ROOT_DIR/.github/workflows/codeql.yml" || fail 'CodeQL compila innecesariamente en vez de usar el modo compatible Rust'
grep -Fq "advanced-security: \${{ github.event_name != 'pull_request' || github.event.pull_request.head.repo.full_name == github.repository }}" "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'zizmor no desactiva SARIF en PR externos sin permisos de escritura'
grep -Fq 'permissions:' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'zizmor no declara permisos acotados'
grep -Fq 'security-events: write' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'zizmor no publica hallazgos en Code Scanning'
grep -Fq -- '--auto-fix' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no ofrece autocorrección Rust optativa'
grep -Fq 'cargo_args=(--locked)' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux puede reescribir Cargo.lock durante el análisis'
grep -Fq 'if [[ "$OFFLINE" -eq 0 ]] && [[ -w "$cargo_home_dir/advisory-dbs" ]]; then' "$ROOT_DIR/scripts/build.sh" || fail 'cargo-deny offline no aísla su caché aunque el directorio advisory-dbs sea escribible'
grep -Fq 'OUTPUT_DIR="$output_real"' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux conserva rutas de salida relativas al cambiar de directorio'
grep -Fq 'RELEASE_DIR="$release_real"' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux conserva rutas de release relativas al cambiar de directorio'
grep -Fq 'run_cargo_audit()' "$ROOT_DIR/scripts/build.sh" || fail 'cargo-audit offline no aísla su caché compartida'
grep -Fq '[AUTO-FIX]' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no marca las autocorrecciones'
grep -Fq '[AUTO-FIXED]' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no enumera archivos Rust autocorregidos'
grep -Fq 'Normalizando formato después de Clippy' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no normaliza formato tras Clippy'
grep -Fq 'Reescaneando Clippy estricto' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no vuelve a escanear tras aplicar autocorrecciones'
grep -Fq 'cargo clippy --manifest-path "$MANIFEST" --workspace --all-features --all-targets' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no pasa Clippy por todas las features y targets del workspace'
grep -Fq 'cargo test --manifest-path "$MANIFEST" --workspace --all-features --all-targets' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no prueba todas las features y targets del workspace'
grep -Fq 'STRICT_SECURITY' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no hace obligatorios los escáneres en modo estricto'
grep -Fq 'audit_args+=(--no-fetch)' "$ROOT_DIR/scripts/build.sh" || fail 'modo offline no impide que cargo-audit intente acceder a la red'
grep -Fq '[switch]$StrictSecurity' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no ofrece auditoría de dependencias estricta'
grep -Fq '[switch]$AutoFix' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no ofrece autocorrección Rust optativa'
grep -Fq -- "-cnotin @('true', 'false')" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no sanea el booleano de incremental heredado inválido para Cargo'
grep -Fq "\$cargoArgs = @('build', '--locked'" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows puede resolver dependencias distintas de Cargo.lock'
grep -Fq '[AUTO-FIX]' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no marca las autocorrecciones'
grep -Fq '[AUTO-FIXED]' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no enumera archivos Rust autocorregidos'
grep -Fq 'rustfmt normalizó el resultado de Clippy' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no normaliza formato tras Clippy'
grep -Fq 'Invoke-RustQualityChecks' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no reescanea formato y Clippy tras las autocorrecciones'
grep -Fq 'Invoke-RustSecurityAudit' "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no revisa vulnerabilidades/licencias/fuentes'
grep -Fq "\$clippyCheck = @('clippy', '--all-features', '--locked', '--manifest-path', \$CargoManifest, '--workspace', '--all-targets', '--target', \$Target" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no pasa Clippy por todas las features y targets del workspace con lock estricto'
grep -Fq "Invoke-Cargo @('test', '--all-features', '--all-targets', '--locked', '--manifest-path', \$CargoManifest, '--workspace', '--target', \$Target)" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no prueba todas las features y targets del workspace'
grep -Fq "\$formatCheck = @('fmt', '--manifest-path', \$CargoManifest, '--all', '--', '--check')" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no valida el formato de todo el workspace Rust'
grep -Fq 'cargo fmt --manifest-path "$MANIFEST" --all -- --check' "$ROOT_DIR/scripts/build.sh" || fail 'builder Linux no valida el formato de todo el workspace Rust'
grep -Fq "Invoke-Cargo @('audit', '--file'" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no actualiza y ejecuta cargo-audit'
grep -Fq "Invoke-Cargo @('deny', '--manifest-path'" "$ROOT_DIR/scripts/build.ps1" || fail 'builder Windows no ejecuta cargo-deny'
grep -Fq 'Exigir auditoría estricta de seguridad y continuar la build incremental' "$ROOT_DIR/scripts/build.ps1" || fail 'menú Windows no permite exigir auditoría estricta'
grep -Fq 'marca como corregidos los hallazgos' "$ROOT_DIR/README.md" || fail 'documentación no explica cómo se actualiza el estado de hallazgos'
grep -Fq 'no sustituye el análisis' "$ROOT_DIR/README.md" || fail 'documentación no advierte del conflicto CodeQL default/advanced'
grep -Fq 'Wine no emula el firmware ni el arranque real del' "$ROOT_DIR/README.md" || fail 'README no delimita las pruebas Wine frente al firmware real'
if grep -Fq 'para una Wine no se considera' "$ROOT_DIR/README.md"; then
    fail 'README conserva la frase rota de la guía de arranque'
fi
grep -Fq 'actionlint -color' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'falta la validación estática de GitHub Actions'
grep -Fq 'shellcheck --severity=error' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'falta ShellCheck para scripts Bash'
grep -Fq 'zizmor --offline .github' "$ROOT_DIR/tests/static-security.sh" || fail 'la revisión estática local omite el modo offline de zizmor'
codeql_action_ref="$(sed -n 's/.*github\/codeql-action\/init@\([^ ]*\).*/\1/p' "$ROOT_DIR/.github/workflows/codeql.yml" | head -n1)"
[[ -n "$codeql_action_ref" ]] || fail 'CodeQL no tiene un commit fijado para init'
grep -Fq "github/codeql-action/upload-sarif@$codeql_action_ref" "$ROOT_DIR/.github/workflows/scorecard.yml" ||
    fail 'Scorecard usa una versión distinta de codeql-action/upload-sarif'
grep -Fq 'gitleaks/gitleaks-action@' "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'falta el escaneo de secretos Gitleaks'
grep -Fq 'Block newly introduced moderate-or-higher vulnerabilities' "$ROOT_DIR/.github/workflows/dependency-review.yml" || fail 'el nombre de Dependency Review no coincide con la severidad que bloquea'
grep -Fq 'fail-on-severity: moderate' "$ROOT_DIR/.github/workflows/dependency-review.yml" || fail 'Dependency Review no bloquea vulnerabilidades moderadas o superiores'
grep -Fq "GITLEAKS_ENABLE_COMMENTS: 'false'" "$ROOT_DIR/.github/workflows/workflow-security.yml" || fail 'Gitleaks puede comentar pull requests con resultados'
grep -Fq 'actions/dependency-review-action@' "$ROOT_DIR/.github/workflows/dependency-review.yml" || fail 'falta la acción de revisión de dependencias'
grep -Fq 'actions/upload-artifact@' "$ROOT_DIR/.github/workflows/ci.yml" || fail 'falta la subida de artefactos CI'
grep -Fq 'fail-on-severity: moderate' "$ROOT_DIR/.github/workflows/dependency-review.yml" || fail 'la revisión de dependencias no bloquea vulnerabilidades moderadas o peores'
grep -Fq 'package-ecosystem: cargo' "$ROOT_DIR/.github/dependabot.yml" || fail 'Dependabot no mantiene las dependencias Rust'
